function isAnagram(a, b) {
  if (a.length !== b.length) return false
  const count = new Map()
  for (const ch of a) count.set(ch, (count.get(ch) || 0) + 1)
  for (const ch of b) {
    const left = (count.get(ch) || 0) - 1
    if (left < 0) return false
    count.set(ch, left)
  }
  return true
}

